  "claim_id": "C007",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C007.main",
    "value": "Existing events should be linked by account and schedule identifiers, with draft-to-publication lineage checked.",
    "scope": "A bounded cohort of new accounts; the procedure proposes verification rather than assuming identifier linkage is correct.",
    "provenance": {
      "refs": [
        {
          "source_id": "P002",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P002 supplies the cohort bound, identifier-based linkage and draft-to-publication lineage check."
    }
  },
  "signal_basis": {
    "component_id": "C007.signal_basis",
    "value": "Link account and schedule events and inspect identities and versions for continuity. The relevant signal is an internally consistent sequence connecting account creation, preparation, draft versions and publication, distinguishing reported offline activity from logged events.",
    "scope": "Proposed observations within the bounded cohort, assumed to occur for this judgment. Documentary consistency does not prove correct identity linkage, truthful reporting or absence of unrecorded offline work.",
    "provenance": {
      "refs": [
        {
          "source_id": "P002",
          "role": "SUPPORT"
        },
        {
          "source_id": "P005",
          "role": "SUPPORT"
