          "role": "SUPPORT"
        },
        {
          "source_id": "P021",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans provide the linkage and inspection procedure, continuity signal, prospective status and limits on what consistent documentation establishes."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C007.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The bounded procedural claim requires no unresolved empirical relation to supply its warrant."
    }
  },
  "rationale": "Linking identifiers and checking draft-to-publication lineage directly serves the stated task of inspecting documented continuity. The claim recommends a verification procedure without asserting that identifiers are necessarily correct or that continuity establishes customer outcomes.",
  "uncertainty": "Actual identity accuracy remains limited by recording and linkage reliability; this does not undermine the bounded recommendation to check it.",
  "anomalies": []
}
